$content = @"
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Flappy Bird</title>
    <style>
        body {
            margin: 0;
            padding: 20px;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            background-color: #333;
            font-family: 'Arial', sans-serif;
        }
        #game-container {
            position: relative;
            width: 400px;
            height: 600px;
            border: 4px solid #fff;
            border-radius: 10px;
            overflow: hidden;
            background-color: #70c5ce;
        }
        #bird {
            position: absolute;
            width: 34px;
            height: 24px;
            background-color: yellow;
            border-radius: 5px;
            left: 50px;
            top: 200px;
            transition: transform 0.1s ease;
        }
        #bird::after {
            content: '';
            position: absolute;
            right: -8px;
            top: 5px;
            width: 8px;
            height: 8px;
            background-color: white;
            border-radius: 50%;
        }
        .pipe {
            position: absolute;
            width: 52px;
            background-color: green;
            border-radius: 10px 10px 0 0;
        }
        #score-display {
            position: absolute;
            top: 10px;
            left: 0;
            right: 0;
            text-align: center;
            font-size: 32px;
            color: white;
            text-shadow: 2px 2px 4px rgba(0,0,0,0.5);
        }
        #start-screen {
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            background-color: rgba(0,0,0,0.6);
            color: white;
            font-size: 24px;
            cursor: pointer;
        }
        #game-over-screen {
            display: none;
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            background-color: rgba(0,0,0,0.7);
            color: white;
        }
    </style>
</head>
<body>
    <div id="game-container">
        <div id="score-display">0</div>
        <div id="bird"></div>
        <div id="start-screen" style="display:flex">
            <p>Click or Press Space to Start</p>
            <p style="font-size:16px">Press SPACE or CLICK to flap</p>
        </div>
        <div id="game-over-screen" style="display:none">
            <p style="font-size:28px;font-weight:bold">GAME OVER</p>
            <p style="font-size:20px">Score: <span id="final-score">0</span></p>
            <p style="font-size:16px">Press SPACE to restart</p>
        </div>
    </div>
    <script>
        const container = document.getElementById('game-container');
        const bird = document.getElementById('bird');
        const scoreDisplay = document.getElementById('score-display');
        const startScreen = document.getElementById('start-screen');
        const gameOverScreen = document.getElementById('game-over-screen');
        const finalScore = document.getElementById('final-score');

        let gameRunning = false;
        let birdY = 200;
        let birdVelocity = 0;
        let gravity = 0.5;
        let jumpStrength = -8;
        let pipeX = 400;
        let pipeGap = 150;
        let pipeSpeed = 3;
        let score = 0;
        let pipes = [];
        let animationId;

        function resetGame() {
            birdY = 200;
            birdVelocity = 0;
            bird.style.top = birdY + 'px';
            bird.style.transform = 'rotate(0deg)';

            container.innerHTML = `
                <div id="score-display">0</div>
                <div id="bird"></div>
                <div id="start-screen" style="display:flex">
                    <p>Click or Press Space to Start</p>
                    <p style="font-size:16px">Press SPACE or CLICK to flap</p>
                </div>
                <div id="game-over-screen" style="display:none">
                    <p style="font-size:28px;font-weight:bold">GAME OVER</p>
                    <p style="font-size:20px">Score: <span id="final-score">0</span></p>
                    <p style="font-size:16px">Press SPACE to restart</p>
                </div>
            `;

            pipes = [];
            score = 0;
            scoreDisplay.textContent = '0';
            gameRunning = false;
            startScreen.style.display = 'flex';
            gameOverScreen.style.display = 'none';
            finalScore.innerHTML = '0';
        }

        function flap() {
            if (!gameRunning) {
                startGame();
                return;
            }
            birdVelocity = jumpStrength;
            bird.style.transform = 'rotate(-30deg)';
        }

        function startGame() {
            gameRunning = true;
            startScreen.style.display = 'none';

            container.innerHTML = `
                <div id="score-display">0</div>
                <div id="bird"></div>
            `;
            scoreDisplay.textContent = '0';

            animationId = setInterval(update, 16);
        }

        function update() {
            birdVelocity += gravity;
            birdY += birdVelocity;
            bird.style.top = birdY + 'px';

            if (birdVelocity > 5) {
                bird.style.transform = 'rotate(70deg)';
            } else if (birdVelocity < -5) {
                bird.style.transform = 'rotate(-30deg)';
            } else {
                bird.style.transform = 'rotate(0deg)';
            }

            // Pipe generation
            if (pipeX <= 52) {
                pipeX = 400;
                const minPipeHeight = 50;
                const maxPipeHeight = 500 - minPipeHeight - pipeGap;
                const randomHeight = Math.floor(Math.random() * (maxPipeHeight - minPipeHeight + 1) + minPipeHeight);

                pipes.push({
                    x: 400,
                    y: 0,
                    height: randomHeight,
                    passed: false
                });

                pipeX = 400;
            }

            // Pipe movement and collision detection
            pipes.forEach(pipe => {
                pipe.x -= pipeSpeed;
                pipe.y -= Math.abs(birdVelocity);

                if (pipe.x <= 52 && !pipe.passed) {
                    score++;
                    scoreDisplay.textContent = score;
                    pipe.passed = true;
                }

                // Collision with top pipe
                if (birdY < pipe.y + pipe.height - 24 && 
                    birdY > pipe.y - 36 && 
                    bird.style.left <= pipe.x + 52) {
                    gameOver();
                }

                // Collision with bottom pipe
                const bottomPipeY = pipe.y + pipe.height + pipeGap;
                if (birdY + 24 > bottomPipeY && 
                    birdY < bottomPipeY - 36 && 
                    bird.style.left <= pipe.x + 52) {
                    gameOver();
                }
            });

            // Collision with ground or ceiling
            if (birdY >= 576 || birdY <= 0) {
                gameOver();
            }

            if (gameRunning) {
                animationId = requestAnimationFrame(update);
            } else {
                clearInterval(animationId);
            }
        }

        function gameOver() {
            gameRunning = false;
            cancelAnimationFrame(animationId);
            finalScore.innerHTML = score;

            container.innerHTML = `
                <div id="score-display">0</div>
                <div id="bird"></div>
                <div id="game-over-screen">
                    <p style="font-size:28px;font-weight:bold">GAME OVER</p>
                    <p style="font-size:20px">Score: <span id="final-score">${score}</span></p>
                    <p style="font-size:16px">Press SPACE to restart</p>
                </div>
            `;
            gameOverScreen.style.display = 'flex';
        }

        function init() {
            container.addEventListener('click', flap);
            document.addEventListener('keydown', (e) => {
                if (e.code === 'Space') {
                    e.preventDefault();
                    if (!gameRunning && startScreen.style.display !== 'none') {
                        flap();
                    } else if (gameRunning) {
                        flap();
                    } else if (gameOverScreen.style.display !== 'none') {
                        resetGame();
                        flap();
                    }
                }
            });
        }

        init();
    </script>
</body>
</html>
"@
$content | Out-File -FilePath $file -Encoding UTF8
Write-Host "Flappy Bird game created at: C:/Users/Public/Shared/temp/flappy.html"
